package com.ute.uteexpress.operations;

import com.ute.uteexpress.config.SecurityConfig;
import com.ute.uteexpress.controller.*;
import com.ute.uteexpress.dto.operations.*;
import com.ute.uteexpress.entity.*;
import com.ute.uteexpress.enums.*;
import com.ute.uteexpress.security.*;
import com.ute.uteexpress.service.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.autoconfigure.EnableAutoConfiguration;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.*;
import org.springframework.test.context.TestPropertySource;
import org.springframework.test.context.junit.jupiter.web.SpringJUnitWebConfig;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import org.springframework.web.context.WebApplicationContext;
import static com.ute.uteexpress.operations.OperationsJdbcFixture.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup;

/** Actual MVC/security/Thymeleaf and customer/Manager JDBC services; quote write service is outside this context. */
@SpringJUnitWebConfig(CustomerSupportMvcTests.Config.class)
@TestPropertySource(properties={"spring.autoconfigure.exclude=org.springframework.boot.jdbc.autoconfigure.DataSourceAutoConfiguration,org.springframework.boot.hibernate.autoconfigure.HibernateJpaAutoConfiguration,org.springframework.boot.data.jpa.autoconfigure.DataJpaRepositoriesAutoConfiguration,org.springframework.boot.flyway.autoconfigure.FlywayAutoConfiguration","spring.flyway.enabled=false","spring.sql.init.mode=never","debug=false","logging.level.root=INFO"})
class CustomerSupportMvcTests extends CustomerSupportJdbcSupport {
    @TestConfiguration(proxyBeanMethods=false) @EnableAutoConfiguration
    @Import({OperationsJdbcConfig.class,SecurityConfig.class,SecurityErrorHandlers.class,AuthenticationResponseHandlers.class,DatabaseUserDetailsService.class,
        CustomerSupportController.class,CustomerSupportErrorAdvice.class,ManagerTicketController.class,OperationsDashboardController.class,OperationsErrorAdvice.class,
        AuthController.class,NotificationController.class,UserShipmentController.class,UserShipmentService.class})
    static class Config {@Bean QuoteService quotes(){return org.mockito.Mockito.mock(QuoteService.class);}}
    @Autowired WebApplicationContext context;MockMvc mvc;
    @BeforeEach void mvc(){mvc=webAppContextSetup(context).apply(springSecurity()).defaultResponseCharacterEncoding(java.nio.charset.StandardCharsets.UTF_8).build();}
    MockHttpServletRequestBuilder ownerGet(String path){return get(path).with(user(f.owner.getEmail()).roles("USER"));}
    MockHttpServletRequestBuilder ownerPost(String path){return post(path).with(user(f.owner.getEmail()).roles("USER")).with(csrf());}
    MockHttpServletRequestBuilder createPost(String token){return ownerPost("/account/support").param("shipmentId",shipment.getId().toString()).param("category","DELAY").param("subject","Need support").param("content","Customer description").param("token",token);}
    @Test void emptyPortalAndNewFormRenderResponsiveVietnameseHtmlWithCsrf()throws Exception{
        mvc.perform(ownerGet("/account/support")).andExpect(status().isOk()).andExpect(view().name("support/list")).andExpect(header().string("Cache-Control","no-store")).andExpect(result->{String html=result.getResponse().getContentAsString();assertTrue(html.contains("Chưa có yêu cầu hỗ trợ"));assertTrue(html.contains("width=device-width"));assertTrue(html.contains("/css/vendor/bootstrap.min.css"));assertTrue(html.contains("/js/notifications.js"));});
        mvc.perform(ownerGet("/account/support/new")).andExpect(status().isOk()).andExpect(result->{String html=result.getResponse().getContentAsString();assertTrue(html.contains(shipment.getTrackingNumber()));assertTrue(html.contains("name=\"_csrf\""));assertTrue(html.contains("maxlength=\"2000\""));assertFalse(html.contains("name=\"priority\""));assertFalse(html.contains("name=\"branchId\""));});
    }
    @Test void actualCreatePostIgnoresForgedOwnerActorSourceStatusPriorityAndAssignee()throws Exception{
        mvc.perform(createPost(token()).param("requesterUserId",f.other.getId().toString()).param("userId",f.other.getId().toString()).param("senderId",f.other.getId().toString()).param("createdBy",f.manager.getId().toString()).param("source","MANAGER_COUNTER").param("status","CLOSED").param("priority","URGENT").param("assignedManager",f.manager.getId().toString()).param("branchId",f.foreign.getId().toString()))
            .andExpect(status().is3xxRedirection()).andExpect(redirectedUrlPattern("/account/support/*"));
        var t=ticketRows.findAll().getFirst();assertEquals(f.owner.getId(),t.getUser().getId());assertEquals(f.owner.getId(),t.getCreatedBy().getId());assertEquals(TicketSource.CUSTOMER,t.getSource());assertEquals(TicketStatus.OPEN,t.getStatus());assertEquals(TicketPriority.MEDIUM,t.getPriority());assertNull(t.getAssignedManager());assertEquals(f.source.getId(),t.getHandlingBranch().getId());
    }
    @Test void creationDoubleSubmitReturnsSameLocation()throws Exception{String token=token();var first=mvc.perform(createPost(token)).andExpect(status().is3xxRedirection()).andReturn();mvc.perform(createPost(token)).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl(first.getResponse().getRedirectedUrl()));assertEquals(1,ticketRows.count());}
    @Test void invalidCreateRendersValidationAndPreservesTypedContent()throws Exception{mvc.perform(createPost(token()).with(request->{request.setParameter("subject"," ");return request;})).andExpect(status().isBadRequest()).andExpect(view().name("support/new")).andExpect(result->{String html=result.getResponse().getContentAsString();assertTrue(html.contains("Vui lòng kiểm tra"));assertTrue(html.contains("Customer description"));});assertEquals(0,ticketRows.count());}
    @Test void routeConfigurationFailureHasHelpfulErrorAndNoPartialTicket()throws Exception{db(()->{em.createQuery("delete from SupportTicketRoute").executeUpdate();return null;});mvc.perform(createPost(token())).andExpect(status().isBadRequest()).andExpect(view().name("support/error")).andExpect(result->assertTrue(result.getResponse().getContentAsString().contains("Chưa có cấu hình chi nhánh hỗ trợ")));assertEquals(0,ticketRows.count());}
    @Test void newFormShipmentPreselectionIsReauthorized()throws Exception{mvc.perform(ownerGet("/account/support/new").param("shipmentId",shipment.getId().toString())).andExpect(status().isOk());mvc.perform(get("/account/support/new").with(user(f.other.getEmail()).roles("USER")).param("shipmentId",shipment.getId().toString())).andExpect(status().isNotFound());}
    @Test void htmlEscapesTitleOriginalDescriptionAndBothMessageAuthors()throws Exception{
        var c=createCommand();Long id=tickets.createCustomer(new CustomerTicketCommands.Create(c.shipmentId(),c.category(),"<script>alert(1)</script>","<img src=x onerror=alert(1)>",c.token()));tickets.customerMessage(id,message(id,"<svg onload=alert(2)>"));
        as(f.manager,"ROLE_MANAGER");tickets.note(id,new TicketCommands.Message(version(id),"INTERNAL-DO-NOT-SEND"));tickets.reply(id,new TicketCommands.Message(version(id),"<script>alert(3)</script>"));
        mvc.perform(ownerGet("/account/support/"+id)).andExpect(status().isOk()).andExpect(result->{String html=result.getResponse().getContentAsString();assertTrue(html.contains("&lt;script&gt;alert(1)"));assertTrue(html.contains("&lt;img"));assertTrue(html.contains("&lt;svg"));assertFalse(html.contains("<script>alert("));assertFalse(html.contains("INTERNAL-DO-NOT-SEND"));assertFalse(html.contains(f.manager.getEmail()));assertFalse(html.contains("Thông tin tiếp nhận nội bộ"));assertTrue(html.contains("Chi nhánh hỗ trợ"));});
        mvc.perform(ownerGet("/account/support")).andExpect(status().isOk()).andExpect(result->assertFalse(result.getResponse().getContentAsString().contains("<script>alert(1)")));
    }
    @Test void managerIntakeInitialInternalTextIsNotEvenHiddenInCustomerHtml()throws Exception{as(f.manager,"ROLE_MANAGER");Long id=tickets.create(command(shipment));mvc.perform(ownerGet("/account/support/"+id)).andExpect(status().isOk()).andExpect(result->{String html=result.getResponse().getContentAsString();assertFalse(html.contains("Nội dung tiếp nhận nội bộ"));assertFalse(html.contains("assignedManager"));assertFalse(html.contains("resolutionNotes"));assertFalse(html.contains("/manager/tickets"));});}
    @Test void messagePostUsesPrincipalAndPublicKindDespiteForgedFields()throws Exception{Long id=createCustomer();mvc.perform(ownerPost("/account/support/"+id+"/messages").param("version",version(id).toString()).param("body","Customer addition").param("token",token()).param("kind","INTERNAL").param("authorId",f.manager.getId().toString()).param("status","CLOSED")).andExpect(status().is3xxRedirection());var message=messageRows.findAll().getFirst();assertEquals(TicketMessageKind.PUBLIC,message.getKind());assertEquals(f.owner.getId(),message.getAuthor().getId());assertEquals(TicketStatus.OPEN,ticketRows.findById(id).orElseThrow().getStatus());}
    @Test void messageReplayAndStaleVersionHaveDistinctCorrectOutcomes()throws Exception{Long id=createCustomer();String v=version(id).toString(),token=token();mvc.perform(ownerPost("/account/support/"+id+"/messages").param("version",v).param("body","Once").param("token",token)).andExpect(status().is3xxRedirection());mvc.perform(ownerPost("/account/support/"+id+"/messages").param("version",v).param("body","Once").param("token",token)).andExpect(status().is3xxRedirection());mvc.perform(ownerPost("/account/support/"+id+"/messages").param("version",v).param("body","Stale").param("token",token())).andExpect(status().isConflict()).andExpect(view().name("support/error"));assertEquals(1,messageRows.count());}
    @ParameterizedTest @ValueSource(strings={""," ","\t"})
    void blankMessageFailsValidationInMvc(String body)throws Exception{Long id=createCustomer();mvc.perform(ownerPost("/account/support/"+id+"/messages").param("version",version(id).toString()).param("body",body).param("token",token())).andExpect(status().isBadRequest());assertEquals(0,messageRows.count());}
    @Test void otherOwnerGetsUniform404AcrossReadWriteAndReopen()throws Exception{Long id=createCustomer();mvc.perform(get("/account/support/"+id).with(user(f.other.getEmail()).roles("USER"))).andExpect(status().isNotFound());mvc.perform(get("/account/support/999999").with(user(f.other.getEmail()).roles("USER"))).andExpect(status().isNotFound());for(String action:java.util.List.of("messages","reopen"))mvc.perform(post("/account/support/"+id+"/"+action).with(user(f.other.getEmail()).roles("USER")).with(csrf()).param("version","0").param("body","Attempt").param("token",token())).andExpect(status().isNotFound());}
    @ParameterizedTest @ValueSource(strings={"/account/support","/account/support/new","/account/support/999","/api/account/support"})
    void guestCannotReadAnyCustomerPageOrUndeclaredApi(String path)throws Exception{mvc.perform(get(path).with(anonymous()).accept(org.springframework.http.MediaType.APPLICATION_JSON)).andExpect(status().isUnauthorized());}
    @ParameterizedTest @ValueSource(strings={"ADMIN","MANAGER","SHIPPER"})
    void otherRolesDoNotImplicitlyReceiveCustomerPermissions(String role)throws Exception{mvc.perform(get("/account/support").with(user(f.owner.getEmail()).roles(role))).andExpect(status().isForbidden());mvc.perform(post("/account/support").with(user(f.owner.getEmail()).roles(role)).with(csrf())).andExpect(status().isForbidden());}
    @Test void everyCustomerPostRequiresCsrf()throws Exception{Long id=createCustomer();for(String path:java.util.List.of("/account/support","/account/support/"+id+"/messages","/account/support/"+id+"/reopen"))mvc.perform(post(path).with(user(f.owner.getEmail()).roles("USER"))).andExpect(status().isForbidden());assertEquals(1,eventRows.count());}
    @Test void noGetMutationAndNoCustomerAssignResolveCloseDeleteOrEditEndpoints()throws Exception{Long id=createCustomer();mvc.perform(ownerGet("/account/support/"+id+"/messages")).andExpect(status().isMethodNotAllowed());for(String operation:java.util.List.of("assign","status","resolve","close","classify"))mvc.perform(ownerPost("/account/support/"+id+"/"+operation)).andExpect(status().isNotFound());mvc.perform(delete("/account/support/"+id).with(user(f.owner.getEmail()).roles("USER")).with(csrf())).andExpect(status().isMethodNotAllowed());assertEquals(TicketStatus.OPEN,ticketRows.findById(id).orElseThrow().getStatus());}
    @Test void userCannotAccessManagerTicketsOrWriteManagerPublicReplies()throws Exception{Long id=createCustomer();mvc.perform(ownerGet("/manager/tickets/"+id)).andExpect(status().isForbidden());mvc.perform(ownerPost("/manager/tickets/"+id+"/reply")).andExpect(status().isForbidden());}
    @Test void lockedOrRoleRevokedUserIsDeniedWithStaleHttpAuthority()throws Exception{Long id=createCustomer();db(()->{em.find(User.class,f.owner.getId()).setStatus(UserStatus.LOCKED);return null;});mvc.perform(ownerGet("/account/support/"+id)).andExpect(status().isForbidden());db(()->{em.find(User.class,f.owner.getId()).setStatus(UserStatus.ACTIVE);em.createQuery("delete from UserRole r where r.user.id=:id").setParameter("id",f.owner.getId()).executeUpdate();return null;});mvc.perform(ownerGet("/account/support")).andExpect(status().isForbidden());}
    @Test void closedDetailShowsPublicResolutionAndReopenRequestButNoMessageForm()throws Exception{Long id=createCustomer();state(id,TicketStatus.CLOSED);mvc.perform(ownerGet("/account/support/"+id)).andExpect(status().isOk()).andExpect(result->{String html=result.getResponse().getContentAsString();assertTrue(html.contains("Kết quả công khai chính thức"));assertTrue(html.contains("Yêu cầu xem xét mở lại"));assertFalse(html.contains("/"+id+"/messages"));});mvc.perform(ownerPost("/account/support/"+id+"/reopen").param("version",version(id).toString()).param("body","Cần xem lại").param("token",token())).andExpect(status().is3xxRedirection());assertEquals(TicketStatus.CLOSED,ticketRows.findById(id).orElseThrow().getStatus());mvc.perform(ownerGet("/account/support/"+id)).andExpect(status().isOk()).andExpect(result->assertTrue(result.getResponse().getContentAsString().contains("đang chờ Manager xem xét")));}
    @Test void invalidFilterPageAndOversizeSizeAreBoundedBeforeQuery()throws Exception{mvc.perform(ownerGet("/account/support").param("filter","ALL'; DROP TABLE users")).andExpect(status().isBadRequest());mvc.perform(ownerGet("/account/support").param("size","51")).andExpect(status().isBadRequest());mvc.perform(ownerGet("/account/support").param("page","-1")).andExpect(status().isBadRequest());mvc.perform(ownerGet("/account/support/new").param("shipmentPage","-1")).andExpect(status().isBadRequest());}
    @Test void managerPagesAndDashboardShowCustomerTicketAndRequestEvents()throws Exception{Long id=createCustomer();state(id,TicketStatus.CLOSED);tickets.requestCustomerReopen(id,message(id,"REOPEN PUBLIC REASON"));mvc.perform(get("/manager/tickets/"+id).with(user(f.manager.getEmail()).roles("MANAGER"))).andExpect(status().isOk()).andExpect(result->{String html=result.getResponse().getContentAsString();assertTrue(html.contains("Khách hàng trực tiếp"));assertTrue(html.contains("REOPEN PUBLIC REASON"));assertTrue(html.contains("Khách hàng yêu cầu mở lại"));});mvc.perform(get("/manager/operations").with(user(f.manager.getEmail()).roles("MANAGER"))).andExpect(status().isOk());}
    @Test void notificationOpenRedirectUsesServerOwnedTicketPathAndRevocationIs404()throws Exception{Long id=createCustomer();as(f.manager,"ROLE_MANAGER");tickets.reply(id,new TicketCommands.Message(version(id),"Public"));notifications.process(event(id,TicketAction.PUBLIC_REPLY));Long notice=notices.findAll().getFirst().getId();mvc.perform(ownerGet("/notifications/"+notice+"/open").param("returnUrl","https://evil.example")).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("/account/support/"+id));mvc.perform(get("/notifications/"+notice+"/open").with(user(f.other.getEmail()).roles("USER"))).andExpect(status().isNotFound());}
    @Test void accountShipmentAndNotificationCenterContainCustomerSupportNavigation()throws Exception{mvc.perform(ownerGet("/account")).andExpect(status().isOk()).andExpect(result->assertTrue(result.getResponse().getContentAsString().contains("/account/support")));mvc.perform(ownerGet("/user/shipments/"+shipment.getId())).andExpect(status().isOk()).andExpect(result->assertTrue(result.getResponse().getContentAsString().contains("/account/support/new?shipmentId="+shipment.getId())));mvc.perform(ownerGet("/notifications")).andExpect(status().isOk()).andExpect(result->assertTrue(result.getResponse().getContentAsString().contains("Hỗ trợ của tôi")));}
}
